import React, { useCallback } from 'react';
import { useParams, Navigate, useNavigate } from 'react-router-dom';
import { TrustyAllVocabGame, TrustyRulesGame } from '../features/Trusty_game';

const TrustyGamePage = () => {
    const { mode, id } = useParams();
    const navigate = useNavigate();

    const handleViewDocs = useCallback((ruleData) => {
        if (ruleData?.path) {
            // Переходимо на сторінку DocViewerPage, передаючи шлях у state
            // Ми використовуємо id правила як частину URL, а реальний шлях через state
            navigate(`/doc/${ruleData.id || 'rule'}`, { 
                state: { directPath: ruleData.path, fromGame: true } 
            });
        }
    }, [navigate]);

    // Вибір гри на основі параметра :mode в URL
    switch (mode) {
        case 'vocab':
            return <TrustyAllVocabGame key={`vocab-${id}`} />;
        case 'rules':
            return <TrustyRulesGame key={`rules-${id}`} onViewDocs={handleViewDocs} />;
        default:
            // Якщо режим не розпізнано, можна редиректнути на головну або показати помилку
            console.warn(`[TrustyGamePage] Unknown mode: ${mode}. Redirecting...`);
            return <Navigate to="/home" replace />;
    }
};

export { TrustyGamePage };
