import {useState, useEffect, useMemo} from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import {useNavigate, useLocation} from 'react-router-dom';
import {appConstants} from "../../../shared/constants/index"
import {useDocTree} from "../../../app/hooks/useDocTree";
import {HoldButton} from "../../../shared/ui";
import {parseSmartTable} from "../utils/smartTableParser";
import {SmartTableToolbar} from "./SmartTableToolbar";
import {SmartTableRender} from "./SmartTableRender";

import css from './DocViewer.module.css';


import { MdArrowBack, MdOutlineAssignmentTurnedIn } from 'react-icons/md';

export const DocViewer = ({docName}) => {
    const [markdownContent, setMarkdownContent] = useState('');
    const [smartTable, setSmartTable] = useState(null);
    const [search, setSearch] = useState('');
    const [selectedFilters, setSelectedFilters] = useState({}); // { grammar: 'v2=v3', priority: 'top50' }
    const [mode, setMode] = useState('full');
    const [showTags, setShowTags] = useState(false);

    const {findNodeById, isLoading} = useDocTree();
    const navigate = useNavigate();
    const location = useLocation();

    // Отримуємо прямий шлях та контекст, якщо вони були передані через навігацію
    const directPath = location.state?.directPath;
    const fromGame = location.state?.fromGame;

    useEffect(() => {
        if (docName && !isLoading) {
            const node = findNodeById(docName);

            let relativePath = '';
            if (directPath) {
                relativePath = directPath;
            } else if (node?.path) {
                relativePath = node.path;
            } else {
                relativePath = `${docName}.md`;
            }

            const cleanPath = relativePath.startsWith('/') ? relativePath.substring(1) : relativePath;
            const fetchUrl = `${appConstants.apiDocUrl}/${cleanPath}`;

            fetch(fetchUrl)
                .then((response) => {
                    if (!response.ok) throw new Error('Document not found');
                    return response.text();
                })
                .then((text) => {
                    setMarkdownContent(text);
                // ...
                    const parsed = parseSmartTable(text);
                    if (parsed) {
                        setSmartTable({
                            config: {
                                ...parsed.config,
                                headers: parsed.headers
                            },
                            data: parsed.data
                        });
                        if (parsed.config.modes && parsed.config.modes.length > 0) {
                            setMode(parsed.config.modes[0]);
                        }
                    } else {
                        setSmartTable(null);
                    }
                // ...
                    // Скидаємо фільтри при зміні документа
                    setSelectedFilters({});
                    setSearch('');
                    setShowTags(false);
                })
                .catch((err) => {
                    console.error(err);
                    setMarkdownContent(`### Помилка завантаження\nНе вдалося завантажити документ: ${docName}`);
                    setSmartTable(null);
                });
        }
    }, [docName, findNodeById, isLoading, directPath]);

    const handleFilterChange = (groupId, value) => {
        setSelectedFilters(prev => ({
            ...prev,
            [groupId]: value
        }));
    };

    const handleClearFilters = () => {
        setSelectedFilters({});
        setSearch('');
    };

    // Логіка фільтрації
    const filteredData = useMemo(() => {
        if (!smartTable) return [];
        return smartTable.data.filter(item => {
            // 1. Пошук за текстом
            const matchesSearch = 
                item.v1.toLowerCase().includes(search.toLowerCase()) ||
                item.translation.toLowerCase().includes(search.toLowerCase());
            
            if (!matchesSearch) return false;

            // 2. Фільтрація за групами тегів (Логічне "І")
            const activeFilterGroups = Object.entries(selectedFilters).filter(([, val]) => val !== '');
            
            for (const [, selectedTagId] of activeFilterGroups) {
                if (!item.tags.includes(selectedTagId)) {
                    return false; 
                }
            }
            
            return true;
        });
    }, [smartTable, search, selectedFilters]);

    if (isLoading) return <div>Завантаження структури...</div>;

    return (
        <div className={css.DocViewer}>
            <div className={css.backButtonContainer}>
                <HoldButton
                    onAction={() => navigate(-1)}
                    className={css.backButton}
                >
                    <div className={css.backBtnContent}>
                        {fromGame ? <MdOutlineAssignmentTurnedIn /> : <MdArrowBack />}
                        <span>{fromGame ? "До результатів" : "Назад"}</span>
                    </div>
                </HoldButton>
            </div>
            
            {smartTable ? (
                <>
                    <SmartTableToolbar 
                        search={search}
                        onSearchChange={setSearch}
                        selectedFilters={selectedFilters}
                        onFilterChange={handleFilterChange}
                        onClearFilters={handleClearFilters}
                        tagGroups={smartTable.config.tagGroups}
                        mode={mode}
                        onModeChange={setMode}
                        availableModes={smartTable.config.modes}
                        showTags={showTags}
                        onToggleTags={setShowTags}
                    />
                    <SmartTableRender 
                        data={filteredData}
                        config={smartTable.config}
                        mode={mode}
                        showTags={showTags}
                    />
                </>
            ) : (
                <ReactMarkdown remarkPlugins={[remarkGfm]}>{markdownContent}</ReactMarkdown>
            )}
        </div>
    );
};

