import React, { createContext, useContext, useMemo } from 'react';
import { useMachine } from '@xstate/react';
import { trustyMachine } from '../lib/trustyMachine';

const TrustyActorContext = createContext();
const TrustyStateContext = createContext();

export const TrustyProvider = ({ children, data, languages, setsCount = 2, config = null, initialHighScore = 0 }) => {
  const [state, send, actor] = useMachine(trustyMachine, {
    input: { data, languages, setsCount, config, initialHighScore }
  });

  const actorValue = useMemo(() => ({ actor, send }), [actor, send]);

  return (
    <TrustyActorContext.Provider value={actorValue}>
      <TrustyStateContext.Provider value={state}>
        {children}
      </TrustyStateContext.Provider>
    </TrustyActorContext.Provider>
  );
};

export const useTrustyActor = () => {
  const context = useContext(TrustyActorContext);
  if (!context) throw new Error('useTrustyActor must be used within TrustyProvider');
  return context;
};

export const useTrustyState = () => {
  const context = useContext(TrustyStateContext);
  if (!context) throw new Error('useTrustyState must be used within TrustyProvider');
  return context;
};
