import React, { useState, useEffect } from 'react';
import { useTrustyActor, useTrustyState } from '../TrustyProvider';
import { trustyConstants as c } from '../../lib/trusty.constants';
import { HoldButton } from '../../../../shared/ui';
import css from './TrustyUI.module.css';

/**
 * UIActions відображає кнопки дій для двигуна раунду.
 */
export const UIActions = () => {
    const { send } = useTrustyActor();
    const state = useTrustyState();
    const [canAction, setCanAction] = useState(false);
    
    const isGameOver = state.matches(c.states.gameOver);
    const isReady = state.matches(c.states.ready);

    useEffect(() => {
        // Додаємо невелику затримку для запобігання випадковим клікам
        setCanAction(false);
        const timer = setTimeout(() => setCanAction(true), 900);
        return () => clearTimeout(timer);
    }, [state.value]);

    let actionLabel = "СТАРТ";
    let actionType = c.events.START;

    if (isGameOver) {
        actionLabel = "Спробувати раунд ще раз";
        actionType = c.events.RETRY;
    } else if (isReady) {
        actionLabel = "ПОЧАТИ РАУНД";
        actionType = c.events.START;
    } else {
        return null;
    }

    return (
        <div className={css.actionsContainer}>
            {/*<div className="bage">UIActions</div>*/}
            <HoldButton 
                onAction={() => canAction && send({ type: actionType })} 
                className={`${css.actionBtn} ${!canAction ? css.disabled : ""}`}
                disabled={!canAction}
            >
                {actionLabel}
            </HoldButton>
        </div>
    );
};
