import React, {createContext, useContext, useEffect, useRef, useMemo, useState, useCallback} from 'react';

import {mainStateMachine} from "../lib/mainStateMachine";
import {useMachine} from "@xstate/react";
import {localStorageKeys as k} from "../index";
import {machine as m} from "../constants/machine.constants";
import {getPlayerScenarioInitData} from "../data/initContext";
import {checkObject} from "../lib/mainStateMachine.helpers";
import {SpeechVoicesContext} from "../../../app/contexts/SpeechVoicesContext";
import {getStoredFilters, saveFilters, filterItems, extractTags} from "../lib/filter";

const ActorContext = createContext();
const StateContext = createContext();
const FilterContext = createContext();

const MainStateMachineProvider = ({playerScenarioObj = {}, children}) => {
    const [state, send, actor] = useMachine(mainStateMachine);
    const [selectedFilters, setSelectedFilters] = useState([]);
    const [rawScenarioItems, setRawScenarioItems] = useState([]);
    
    const isRunning = useRef(false);
    const activePlayerScenarioId = useRef(null);
    const voicesLoaded = useRef(false);
    const latestContextRef = useRef(state.context); 
    
    // Update ref whenever context changes
    useEffect(() => {
        latestContextRef.current = state.context;
    }, [state.context]);

    isRunning.current = !state.matches(m.state.idle);
    const {browserVoicesMap, loading} = useContext(SpeechVoicesContext)

    // SAVE ON UNMOUNT
    useEffect(() => {
        const saveProgress = () => {
            const ctx = latestContextRef.current;
            if (ctx && ctx.lessonId) {
                const progressData = {
                    lessonId: ctx.lessonId,
                    scenarioId: ctx.scenarioId,
                    currentIndex: ctx.currentIndex,
                    currentCardIndex: ctx.currentCardIndex,
                    currentScenarioIndex: ctx.currentScenarioIndex
                };
                localStorage.setItem(k.appContext, JSON.stringify(progressData));
            }
        };

        window.addEventListener('beforeunload', saveProgress);
        return () => {
            saveProgress();
            window.removeEventListener('beforeunload', saveProgress);
        };
    }, []);

    // Handle initial private load and scenario changes
    const applyFilters = useCallback((items, filters) => {
        const filtered = filterItems(items, filters);
        return filtered;
    }, []);

    useEffect(() => {
        const loadInitialData = async () => {
            const currentPSStr = JSON.stringify(activePlayerScenarioId.current);
            const newPSStr = JSON.stringify(playerScenarioObj);
            
            if (currentPSStr !== newPSStr) {
                let initData = await getPlayerScenarioInitData(playerScenarioObj);
                const items = initData.data[0]?.scenarioItems || [];
                setRawScenarioItems(items);
                
                // Initialize filters
                const stored = getStoredFilters(playerScenarioObj.id);
                const initialFilters = stored.length > 0 ? stored : extractTags(items);
                setSelectedFilters(initialFilters);
                
                // CHECK SAVED PROGRESS
                const savedStateStr = localStorage.getItem(k.appContext);
                if (savedStateStr) {
                    const savedProgress = checkObject(savedStateStr);
                    if (savedProgress && 
                        savedProgress.scenarioId === playerScenarioObj.scenarioId && 
                        String(savedProgress.lessonId) === String(playerScenarioObj.id)) {
                        
                        initData = { 
                            ...initData, 
                            currentIndex: savedProgress.currentIndex,
                            currentCardIndex: savedProgress.currentCardIndex,
                            currentScenarioIndex: savedProgress.currentScenarioIndex
                        };
                    }
                }

                if (isRunning.current) {
                    send({type: m.events.IDLE});
                }
                
                send({
                    type: m.events.SET_DATA, 
                    context: {
                        ...initData,
                        data: [{...initData.data[0], scenarioItems: applyFilters(items, initialFilters)}],
                        browserVoicesMap: !loading ? browserVoicesMap : {}
                    }
                });
                
                activePlayerScenarioId.current = playerScenarioObj;
                voicesLoaded.current = !loading;
            }
        }
        
        loadInitialData();
    }, [playerScenarioObj, send, loading, browserVoicesMap, applyFilters]);

    // Apply filters when changed
    useEffect(() => {
        if (rawScenarioItems.length > 0) {
            const filtered = applyFilters(rawScenarioItems, selectedFilters);
            send({
                type: m.events.SET_DATA_AND_RESET,
                context: {
                    ...state.context,
                    data: [{...state.context.data[0], scenarioItems: filtered}]
                }
            });
        }
    }, [selectedFilters, applyFilters, send]);
    
    // ... voice loading useEffect ...

    // Filter context value
    const filterValue = useMemo(() => ({
        selectedFilters,
        setFilters: (filters) => {
            setSelectedFilters(filters);
            saveFilters(playerScenarioObj.id, filters);
        },
        rawScenarioItems
    }), [selectedFilters, playerScenarioObj.id, rawScenarioItems]);

    // STABLE CONTEXT: actor and send never change
    const actorValue = useMemo(() => ({ actor, send }), [actor, send]);

    return (
        <ActorContext.Provider value={actorValue}>
            <StateContext.Provider value={state}>
                <FilterContext.Provider value={filterValue}>
                    {children}
                </FilterContext.Provider>
            </StateContext.Provider>
        </ActorContext.Provider>
    );
};

// Returns STABLE actor and send. Use this for useSelector.
const useMainStateMachine = () => {
    return useContext(ActorContext)
}

// Returns REACTIVE state. Use this only when you need full state updates.
const useMainState = () => {
    return useContext(StateContext)
}

const useFilters = () => {
    return useContext(FilterContext)
}

export {MainStateMachineProvider, useMainStateMachine, useMainState, useFilters};