import React, { useState } from 'react';
import css from './DocViewer.module.css';

export const SmartTableToolbar = ({
    search,
    onSearchChange,
    selectedFilters,
    onFilterChange,
    tagGroups,
    mode,
    onModeChange,
    availableModes = ["full", "study"],
    onClearFilters,
    showTags,
    onToggleTags
}) => {
    const [isSettingsOpen, setIsSettingsOpen] = useState(false);
    const hasTagGroups = tagGroups && Object.keys(tagGroups).length > 0;
    
    // Перевіряємо чи вибраний хоча б один фільтр (крім пошуку)
    const hasActiveFilters = Object.values(selectedFilters).some(val => val !== '');

    return (
        <div className={css.toolbar}>
            <div className={css.toolbarBg}></div>
            <div className={css.mainActions}>
                <div className={css.searchWrapper}>
                    <input
                        type="text"
                        className={css.searchInput}
                        placeholder="Пошук..."
                        value={search}
                        onChange={(e) => onSearchChange(e.target.value)}
                    />
                    {search && (
                        <button className={css.clearSearch} onClick={() => onSearchChange('')}>✕</button>
                    )}
                </div>

                <button 
                    className={`${css.settingsButton} ${isSettingsOpen ? css.active : ''}`}
                    onClick={() => setIsSettingsOpen(!isSettingsOpen)}
                    title="Фільтри та налаштування"
                >
                    <span className={`${css.gearIcon} ${hasActiveFilters ? css.filtersActive : ''}`}>⚙️</span>
                </button>
            </div>


            {isSettingsOpen && (
                <div className={css.settingsPopover}>
                    <div className={css.popoverHeader}>
                        <span>Фільтри та налаштування</span>
                        <button className={css.closeButton} onClick={() => setIsSettingsOpen(false)}>✕</button>
                    </div>
                    
                    <div className={css.popoverContent}>
                        {hasTagGroups && Object.entries(tagGroups).map(([groupId, group]) => (
                            <div key={groupId} className={css.settingRow}>
                                <div className={css.groupLabel}>{group.label}</div>
                                <div className={css.chipGroup}>
                                    <button
                                        className={`${css.chip} ${!selectedFilters[groupId] ? css.chipActive : ''}`}
                                        onClick={() => onFilterChange(groupId, '')}
                                    >
                                        Всі
                                    </button>
                                    {Object.entries(group.tags).map(([tagId, tagLabel]) => (
                                        <button
                                            key={tagId}
                                            className={`${css.chip} ${selectedFilters[groupId] === tagId ? css.chipActive : ''}`}
                                            onClick={() => onFilterChange(groupId, tagId)}
                                        >
                                            {tagLabel}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        ))}

                        <div className={css.settingRow}>
                            <div className={css.groupLabel}>Режим відображення</div>
                            <div className={css.chipGroup}>
                                {availableModes.map(m => (
                                    <button
                                        key={m}
                                        className={`${css.chip} ${mode === m ? css.chipActive : ''}`}
                                        onClick={() => onModeChange(m)}
                                    >
                                        {m === 'study' ? 'Навчання' : 'Повний'}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div className={css.settingRow}>
                            <div className={css.groupLabel}>Показувати теги</div>
                            <div className={css.chipGroup}>
                                <button
                                    className={`${css.chip} ${showTags ? css.chipActive : ''}`}
                                    onClick={() => onToggleTags(true)}
                                >
                                    Так
                                </button>
                                <button
                                    className={`${css.chip} ${!showTags ? css.chipActive : ''}`}
                                    onClick={() => onToggleTags(false)}
                                >
                                    Ні
                                </button>
                            </div>
                        </div>
                    </div>

                    <div className={css.popoverFooter}>
                        <button className={css.clearAllButton} onClick={onClearFilters}>
                            Скинути все
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};
