import React, { useId } from 'react';
import uiCss from './TrustyUI.module.css';

/**
 * "Глупий" компонент для вибору опцій через Radio buttons.
 * 
 * @param {string} title - Заголовок секції
 * @param {Array} options - Масив опцій для radio [{id, name, hint}]
 * @param {string} value - Поточне вибране значення
 * @param {Function} onChange - Обробник зміни значення
 * @param {string} direction - Орієнтація списку radio ('column' або 'row')
 */
const TrustyRadioSelector = ({
    title = "Оберіть складність",
    options = [],
    value,
    onChange,
    direction = 'column'
}) => {
    const groupId = useId();

    return (
        <div className={uiCss.frame}>
            {title && <div className={uiCss.frameLabel}>{title}</div>}

            <div className={uiCss.difficultyList} style={{flexDirection: direction}}>
                {options.map((option) => (
                    <label
                        key={option.id}
                        className={`${uiCss.difficultyRow} ${uiCss.rowBackground} ${value === option.id ? uiCss.active : ''}`}
                    >
                        <input
                            type="radio"
                            name={groupId}
                            value={option.id}
                            checked={value === option.id}
                            onChange={(e) => onChange(e.target.value)}
                            className={uiCss.radioInput}
                        />
                        <div className={uiCss.difficultyInfo}>
                            <span className={uiCss.difficultyName}>{option.name}</span>
                            {option.hint && <span className={uiCss.difficultyHint}>{option.hint}</span>}
                        </div>
                    </label>
                ))}
            </div>
        </div>
    );
};

export default TrustyRadioSelector;
