/**
 * Спеціалізований парсер для формату Trusty Rules.
 * ПОВЕРТАЄ: Плоский масив об'єктів для ігрового двигуна.
 */
function parseTrustyRulesDSL(content) {
    if (!content) return [];
    const lines = content.split('\n');
    const items = [];
    let currentSection = '';

    lines.forEach(line => {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith('#')) return;

        if (trimmed.startsWith('##')) {
            currentSection = trimmed.replace('##', '').trim();
            return;
        }

        if (trimmed.startsWith('-')) {
            const parts = trimmed.substring(1).split('|').map(p => p.trim());
            const question = parts[0];
            const variants = parts[1] ? parts[1].split(',').map(v => v.trim()) : [];
            
            const newItem = {
                type: 'rules',
                section: currentSection,
                question: question,
                answer: variants[0] || '', // Перший варіант - завжди правильний
                variants: variants,
                id: Math.random().toString(36).substr(2, 9) 
            };
            items.push(newItem);
            return;
        }

        const lastItem = items[items.length - 1];
        if (lastItem && trimmed.startsWith('[')) {
            if (trimmed.includes('rule:')) {
                const match = trimmed.match(/rule:\s*(.*?)\]/);
                if (match) lastItem.rule = match[1].trim();
            }
            if (trimmed.includes('context:')) {
                const match = trimmed.match(/context:\s*"(.*?)"\]/) || trimmed.match(/context:\s*(.*?)\]/);
                if (match) lastItem.context = match[1].trim();
            }
        }
    });

    return items;
}

/**
 * Парсер для мета-даних правил (бібліотек).
 * Перетворює DSL у зручний об'єкт { RuleID: { title, description } }
 */
function parseRulesMetaDSL(content) {
    if (!content) return {};
    const lines = content.split('\n');
    const result = {};
    let currentRule = null;

    lines.forEach(line => {
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith('#')) return;

        if (trimmed.startsWith('[')) {
            currentRule = trimmed.replace('[', '').replace(']', '').trim();
            result[currentRule] = {};
            return;
        }

        if (currentRule && trimmed.includes(':')) {
            const separatorIndex = trimmed.indexOf(':');
            const key = trimmed.substring(0, separatorIndex).trim().toLowerCase();
            const value = trimmed.substring(separatorIndex + 1).trim();
            result[currentRule][key] = value;
        }
    });

    return result;
}

/**
 * Класичний парсер для словників.
 */
function parseVocabularyDSL(content) {
    if (!content) return [];
    const lines = content.split('\n');
    const lessons = [];
    let currentLesson = null;
    let currentType = '';
    let currentItem = null;
    let pendingTranslations = [];

    function finalizeItem() {
        if (currentItem && pendingTranslations.length > 0) {
            const combinedText = pendingTranslations.join(' ');
            const parts = combinedText.split('|').map(p => p.trim()).filter(p => p.length > 0);

            currentLesson.meta.langs.forEach((lang, index) => {
                if (parts[index]) {
                    currentItem.translations[lang] = parts[index];
                }
            });
            pendingTranslations = [];
        }
    }

    lines.forEach(line => {
        const trimmed = line.trim();
        if (!trimmed) return;

        if (trimmed.startsWith('# Title:')) {
            finalizeItem();
            if (currentLesson) lessons.push(currentLesson);
            currentLesson = {
                title: trimmed.replace('# Title:', '').trim(),
                meta: { langs: [], item_types: new Set() },
                scenarioItems: []
            };
            return;
        }

        if (!currentLesson) return;

        if (trimmed.startsWith('# Lang:')) {
            const langsMatch = trimmed.match(/\[(.*?)\]/);
            const langsContent = langsMatch ? langsMatch[1] : trimmed.replace('# Lang:', '').trim();
            currentLesson.meta.langs = langsContent.split('/').map(l => l.trim());
            return;
        }

        if (trimmed.startsWith('##')) {
            finalizeItem();
            currentType = trimmed.replace('##', '').trim().toLowerCase();
            currentLesson.meta.item_types.add(currentType);
            return;
        }

        if (trimmed.startsWith('-')) {
            finalizeItem();
            currentItem = { type: currentType, translations: {}, tags: [] };
            currentLesson.scenarioItems.push(currentItem);
            const textAfterDash = trimmed.substring(1).trim();
            if (textAfterDash) pendingTranslations.push(textAfterDash);
            return;
        }

        if (currentItem && trimmed.startsWith('[')) {
            finalizeItem();
            if (trimmed.includes('tags:')) {
                const tagsMatch = trimmed.match(/tags:\s*(.*?)\]/);
                if (tagsMatch) currentItem.tags = tagsMatch[1].split(',').map(t => t.trim());
            }
            return;
        }

        if (currentItem) pendingTranslations.push(trimmed);
    });

    finalizeItem();
    if (currentLesson) lessons.push(currentLesson);
    if (lessons.length > 0) {
        lessons.forEach(l => l.meta.item_types = Array.from(l.meta.item_types));
    }
    return lessons;
}

/**
 * Парсер для структури документації (DocTree DSL).
 * Перетворює текстовий формат у рекурсивне дерево об'єктів.
 */
function parseDocTreeDSL(content) {
    if (!content) return [];
    const lines = content.split('\n');
    const root = [];
    const stack = [];

    lines.forEach((line, index) => {
        const trimmed = line.trim();
        if (!trimmed) return;

        const nodeMatch = trimmed.match(/^(#+)\s*\[(.*?)\]/);

        if (nodeMatch) {
            const level = nodeMatch[1].length;
            const id = nodeMatch[2];

            const newNode = {
                id,
                level,
                title: id,
                children: []
            };

            while (stack.length >= level) {
                stack.pop();
            }

            if (stack.length === 0) {
                root.push(newNode);
            } else {
                const parent = stack[stack.length - 1];
                parent.children.push(newNode);
            }

            stack.push(newNode);
        } else if (stack.length > 0 && trimmed.includes(':')) {
            const separatorIndex = trimmed.indexOf(':');
            const key = trimmed.substring(0, separatorIndex).trim().toLowerCase();
            const value = trimmed.substring(separatorIndex + 1).trim();
            const lastNode = stack[stack.length - 1];
            lastNode[key] = value;
        }
    });

    return root;
}

/**
 * Головний парсер-фасад, який вибирає стратегію на основі формату.
 */
export function parseDSL(content, format = 'vocabulary') {
    switch (format) {
        case 'doctree':
            return parseDocTreeDSL(content);
        case 'rules':
            return parseTrustyRulesDSL(content);
        case 'rules_meta':
            return parseRulesMetaDSL(content);
        case 'vocabulary':
        default:
            return parseVocabularyDSL(content);
    }
}
