import {useState, useEffect, useMemo} from 'react';
import {BsFillGearFill} from "react-icons/bs";
import {
    MdRecordVoiceOver,
    MdExtension,
    MdSchool,
    MdTranslate,
    MdLogin,
    MdLogout,
    MdMenuBook
} from "react-icons/md";
import {FontSizeChanger} from "../Components/FontSizeChanger";
import {ThemeSwitcher} from "../Components/ThemeSwitcher";
import {ClearAllStorage} from "../Components/ClearAllStorage"
import {dataLoaderService} from "../../features/player_scenario/services/dataLoaderService";
import {useAuthStore} from "../hooks/useAuthStore";


const useNavLinksConfig = () => {
    const [groups, setGroups] = useState([]);
    const {isAuthorized, logout} = useAuthStore();

    useEffect(() => {
        const loadGroups = async () => {
            const data = await dataLoaderService.getAllGroups();
            setGroups(data || []);
        };
        loadGroups();
    }, [isAuthorized]);

    return useMemo(() => {
        const generateLessonsMenu = (lessons, fileId) => {
            return lessons.map((item, index) => ({
                title: item.title,
                path: `/english/${fileId}-${index}/english_2`,
                permission: ["admin", "manager", "user"]
            }));
        };

        const dynamicMenuItems = groups.map(group => ({
            title: group.name,
            icon: group.name.toLowerCase().includes('vocab') ? MdTranslate : MdSchool,
            children: generateLessonsMenu(group.lessons, group.id)
        }));

        return [
            {
                title: isAuthorized ? "Logout" : "Login",
                icon: isAuthorized ? MdLogout : MdLogin,
                props: {className: "icon"},
                path: isAuthorized ? null : '/login',
                action: isAuthorized ? logout : null,
                permission: ["admin", "manager", "user"]
            },
            {
                title: "Documentation",
                icon: MdMenuBook,
                props: {className: "icon"},
                path: '/docs',
                permission: ["admin", "manager", "user"]
            },
            {
                title: "Test speech synthesis",
                icon: MdRecordVoiceOver,
                props: {className: "icon"},
                path: '/test',
                permission: ["admin", "manager"]
            },

            ...dynamicMenuItems,

            {
                title: "Games",
                icon: MdExtension,
                props: {className: "icon"},
                children: [
                    {
                        title: "Trusty Dictionary",
                        path: '/game/trusty/vocab/global',
                        permission: ["admin", "manager"]
                    },
                    {
                        title: "Trusty Rules",
                        path: '/game/trusty/rules/global',
                        permission: ["admin", "manager"]
                    }
                ]
            },

            {
                title: "Settings",
                group: "footer",
                icon: BsFillGearFill,
                props: {className: "icon"},
                children: [
                    {
                        title: "theme",
                        component: ThemeSwitcher,
                        props: {size: "1.5rem", width: "4rem"}
                    },
                    {
                        component: ClearAllStorage,
                    },
                    {
                        component: FontSizeChanger,
                    },

                ]
            },
        ];
    }, [groups, isAuthorized, logout]);
}
export {useNavLinksConfig};
