import { createMachine, assign, fromCallback } from 'xstate';
import { trustyConstants as c } from './trusty.constants';
import { playSound } from './trustyAudio';
import { gameConfig } from './trusty.config';
import { trustyService } from './trustyService';

export const trustyMachine = createMachine({
  id: 'trustyGame',
  initial: c.states.idle,
  context: ({ input }) => ({
    preparedItems: input?.data || [],
    currentIndex: 0,
    currentPair: null,
    score: 0,
    highScore: input?.initialHighScore || 0, // Початковий рекорд з пропсів
    streak: 0,
    timer: 0,
    scoreFeedback: null,
    timerFeedback: null,
    config: input?.config || gameConfig,
    history: []
  }),
  states: {
    [c.states.idle]: {
      on: {
        [c.events.START]: {
          target: c.states.ready,
          actions: [
            assign(({ context, event }) => {
              const preparedItems = event.data || (context.preparedItems.length > 0 ? context.preparedItems : []);
              
              return {
                preparedItems,
                currentIndex: 0,
                score: 0,
                streak: 0,
                scoreFeedback: null,
                timerFeedback: null,
                history: []
              };
            })
          ]
        }
      }
    },

    [c.states.ready]: {
      entry: assign(({ context }) => ({
        currentPair: context.preparedItems[0] || null,
        timer: Math.min(
            Math.round(context.preparedItems.length * context.config.timing.timePerWord), 
            context.config.timing.timeCapMax
        ),
      })),
      on: {
        [c.events.START]: {
          target: c.states.playing,
          actions: [
            assign({
              score: 0,
              streak: 0,
              currentIndex: 0,
              scoreFeedback: null,
              timerFeedback: null
            })
          ]
        }
      }
    },

    [c.states.playing]: {
      type: 'parallel',
      states: {
        timer: {
          invoke: {
            src: fromCallback(({ sendBack }) => {
              const interval = setInterval(() => sendBack({ type: c.events.TICK }), 1000);
              return () => clearInterval(interval);
            })
          },
          on: {
            [c.events.TICK]: {
              actions: assign({ timer: ({ context }) => Math.max(0, context.timer - 1) })
            }
          }
        },
        gameplay: {
          on: {
            [c.events.PAUSE]: { target: `#trustyGame.${c.states.paused}` },
            [c.events.GUESS]: {
              actions: [
                ({ context, event }) => {
                   const isCorrect = event.guess === context.currentPair?.isCorrect;
                   playSound(isCorrect);
                },
                assign(({ context, event }) => {
                    const result = trustyService.calculateUpdate(context, event.guess, context.config.scoring);
                    const nextIndex = (context.currentIndex + 1) % context.preparedItems.length;

                    const historyItem = {
                        ...context.currentPair,
                        itemNumber: context.currentIndex + 1,
                        userGuess: event.guess,
                        isUserCorrect: event.guess === context.currentPair?.isCorrect,
                        pointsEarned: result.score - context.score,
                        timestamp: Date.now()
                    };

                    return {
                        ...result,
                        scoreFeedback: result.feedback.score,
                        timerFeedback: result.feedback.timer,
                        currentIndex: nextIndex,
                        currentPair: context.preparedItems[nextIndex],
                        history: [...context.history, historyItem]
                    };
                })
              ]
            }
          }
        },
        feedbackManager: {
           initial: 'idle',
           states: {
             idle: {
               on: { [c.events.GUESS]: 'active' }
             },
             active: {
               after: {
                 [gameConfig.timing.feedbackDelay]: {
                   target: 'idle',
                   actions: assign({ scoreFeedback: null, timerFeedback: null })
                 }
               },
               on: {
                 [c.events.GUESS]: {
                   target: 'active',
                   reenter: true
                 }
               }
             }
           }
        }
      },
      always: [
        { 
          target: c.states.gameOver, 
          guard: ({ context }) => context.timer <= 0
        }
      ]
    },

    [c.states.paused]: {
        on: {
            [c.events.RESUME]: c.states.playing
        }
    },

    [c.states.gameOver]: {
      on: {
        [c.events.RETRY]: {
          target: c.states.ready,
          actions: [
            assign({
              score: 0,
              streak: 0,
              scoreFeedback: null,
              timerFeedback: null,
              history: []
            })
          ]
        },
        [c.events.EXIT]: c.states.idle
      }
    }
  }
});
