import React, {useCallback, useState, useMemo, useEffect} from 'react';
import {TrustyGameOrchestrator} from './TrustyGameOrchestrator';
import {dataManagerService} from '../services/dataManagerService';
import {trustyFilterService} from '../services/trustyFilterService';
import {gameConfig} from '../lib/trusty.config';
import uiCss from './TrustyUI/TrustyUI.module.css';
import TrustyRadioSelector from "./TrustyUI/TrustyRadioSelector";
import TrustyFilterDropdown from "./TrustyUI/TrustyFilterDropdown";

/**
 * TrustyVocabOrchestrator - Оркестратор для словникової гри.
 */
export const TrustyVocabOrchestrator = () => {
    const STORAGE_KEY = 'trusty_word_scores';
    const allVocab = useMemo(() => dataManagerService.fetchAllVocab(), []);
    const separator = gameConfig.ui.answerSeparator;

    const detectedLangs = useMemo(() => {
        if (!allVocab || allVocab.length === 0) return {
            set1: gameConfig.languages.set1,
            set2: gameConfig.languages.set2
        };

        const keys = Object.keys(allVocab[0]).filter(k => k !== 'id' && k !== 'sourceFile' && k !== 'question' && k !== 'answer' && k !== 'correctAnswer' && k !== 'isCorrect');

        if (keys.length >= 2) {
            const q = keys[0];
            const a = keys[1];
            return {
                set1: {q, a},
                set2: {q: a, a: q}
            };
        }

        return {
            set1: gameConfig.languages.set1,
            set2: gameConfig.languages.set2
        };
    }, [allVocab]);

    const [currentLangs, setCurrentLangs] = useState(detectedLangs.set1);

    const prepareVocabPairs = useCallback((items, qLang, aLang) => {
        if (!items || items.length === 0) return [];

        return items.map((item, index) => {
            const isCorrect = Math.random() > 0.5;
            let answerText = "";
            let expectedAnswer = item[aLang] || "";

            if (isCorrect) {
                answerText = expectedAnswer;
            } else {
                const otherItems = items.filter((_, idx) => idx !== index);
                const falseItem = otherItems.length > 0
                    ? otherItems[Math.floor(Math.random() * otherItems.length)]
                    : item;
                answerText = falseItem[aLang] || "";
            }

            const questionText = item[qLang] || "";

            return {
                ...item,
                id: item.id,
                question: questionText,
                answer: answerText,
                correctAnswer: `${questionText}${separator}${expectedAnswer}`,
                isCorrect: isCorrect && answerText === expectedAnswer
            };
        }).sort(() => Math.random() - 0.5);
    }, [separator]);

    const fetchData = useCallback((timeCapMax, langs) => {
        const qLang = langs?.q || currentLangs.q;
        const aLang = langs?.a || currentLangs.a;

        const directionalItems = allVocab.map(item => ({
            ...item,
            question: item[qLang],
            answer: item[aLang],
            correctAnswer: `${item[qLang]}${separator}${item[aLang]}`
        }));

        const filtered = trustyFilterService.getGameData(directionalItems, STORAGE_KEY, timeCapMax);

        return prepareVocabPairs(filtered, qLang, aLang);
    }, [prepareVocabPairs, allVocab, currentLangs, separator]);

    const onNextRoundRequest = useCallback((currentData) => {
        const nextLangs = {q: currentLangs.a, a: currentLangs.q};
        setCurrentLangs(nextLangs);

        const nextDirectionalItems = currentData.map(item => ({
            ...item,
            question: item[nextLangs.q],
            answer: item[nextLangs.a],
            correctAnswer: `${item[nextLangs.q]}${separator}${item[nextLangs.a]}`
        }));

        const normalized = trustyFilterService.normalizationMiddleware(nextDirectionalItems, STORAGE_KEY);

        return prepareVocabPairs(normalized, nextLangs.q, nextLangs.a);
    }, [prepareVocabPairs, currentLangs, separator]);

    const getLangLabel = useCallback((l) => {
        if (!l || !l.q || !l.a) return "???";
        const q = l.q.split('-')[0].toUpperCase();
        const a = l.a.split('-')[0].toUpperCase();
        return `${q} ➔ ${a}`;
    }, []);




    const renderStartOverlay = useCallback(() => {
        const l1 = detectedLangs.set1;
        const l2 = detectedLangs.set2;
        const langsOptions = [
            {
                id: "set1",
                name: getLangLabel(l1),
            },
            {
                id: "set2",
                name: getLangLabel(l2),
            }
        ]

        return (
            <div className={uiCss.gameOverInfo}>
                <h3 style={{marginTop: '1rem'}}>
                    Ця гра складається з 2 сетів 
                </h3>


                <TrustyRadioSelector
                    title="Початковий напрямок"
                    options={langsOptions}
                    value={currentLangs.q === l1.q ? "set1" : "set2"}
                    onChange={(id) => setCurrentLangs(detectedLangs[id])}
                    direction="column"
                />


            </div>
        );
    }, [detectedLangs, currentLangs, getLangLabel]);

    return (
        <TrustyGameOrchestrator
            fetchData={fetchData}
            isDoubleSet={true}
            onNextRoundRequest={onNextRoundRequest}
            renderStartOverlay={renderStartOverlay}
            startButtonLabel={`Почати з ${getLangLabel(currentLangs)}`}
            storageKey={STORAGE_KEY}
            resetNotificationText="Ви впевнені, що хочете скинути весь прогрес вивчення слів?"
        />
    );
};

/**
 * TrustyRulesOrchestrator - Оркестратор для гри за правилами.
 */
export const TrustyRulesOrchestrator = ({ onViewDocs }) => {
    const STORAGE_KEY = 'trusty_rules_scores';
    const FILTER_STORAGE_KEY = 'trusty_rules_selected_filter';
    const separator = gameConfig.ui.answerSeparator;

    // Отримуємо всі доступні правила та мета-дані
    const rawRules = useMemo(() => dataManagerService.fetchRulesData(), []);
    const rulesMeta = useMemo(() => dataManagerService.fetchRulesMeta(), []);

    // Отримуємо унікальні типи правил з наявних даних
    const availableRuleIds = useMemo(() => {
        const ids = new Set(rawRules.map(r => r.rule).filter(Boolean));
        return Array.from(ids);
    }, [rawRules]);

    // Форматуємо опції для фільтра (handle both object and array from fetchRulesMeta)
    const filterOptions = useMemo(() => {
        const getHint = (item) => {
            if (!item) return "";
            if (typeof item === 'string') return item;
            if (typeof item === 'object') {
                return item.description || item.hint || item.title || "";
            }
            return "";
        };

        const getName = (id, meta) => {
            if (meta && typeof meta === 'object' && (meta.title || meta.name)) {
                return meta.title || meta.name;
            }
            return id;
        };

        if (!rulesMeta) return availableRuleIds.map(id => ({ id, name: id, hint: "" }));

        if (Array.isArray(rulesMeta)) {
            // Фільтруємо мета-дані, які відповідають наявним у грі правилам
            const matchedMeta = rulesMeta.filter(m => m && m.id && availableRuleIds.includes(m.id));
            
            // Якщо знайшли мета-дані для якихось правил - використовуємо їх
            if (matchedMeta.length > 0) {
                return matchedMeta.map(m => ({
                    id: m.id,
                    name: getName(m.id, m),
                    hint: getHint(m),
                    path: m.path || null
                }));
            }
        }

        // Якщо rulesMeta - це об'єкт-мапа або масив не дав результатів
        return availableRuleIds.map(id => {
            const meta = (rulesMeta && typeof rulesMeta === 'object' && !Array.isArray(rulesMeta)) 
                ? rulesMeta[id] 
                : null;
            return {
                id,
                name: getName(id, meta),
                hint: getHint(meta),
                path: meta?.path || null
            };
        });
    }, [availableRuleIds, rulesMeta]);

    // Стан обраних фільтрів
    const [selectedRuleIds, setSelectedRuleIds] = useState(() => {
        const saved = localStorage.getItem(FILTER_STORAGE_KEY);
        if (saved) {
            try {
                const parsed = JSON.parse(saved);
                if (Array.isArray(parsed) && parsed.length > 0) {
                    // Фільтруємо збережені ID, щоб вони відповідали поточним доступним правилам
                    const valid = parsed.filter(id => availableRuleIds.includes(id));
                    if (valid.length > 0) return valid;
                }
            } catch (e) {
                console.warn("[TrustyRules] Error parsing saved filter", e);
            }
        }
        return availableRuleIds;
    });

    // Зберігаємо вибір у localStorage при зміні
    useEffect(() => {
        localStorage.setItem(FILTER_STORAGE_KEY, JSON.stringify(selectedRuleIds));
    }, [selectedRuleIds]);

    const fetchData = useCallback((timeCapMax) => {
        // Фільтруємо правила за обраними типами
        const filteredByRule = rawRules.filter(r => selectedRuleIds.includes(r.rule));

        const normalizedRules = filteredByRule.map(rule => {
            const question = rule.question || rule.text || "No question";
            const correctValue = rule.variants ? rule.variants[0] : (rule.answer || "No answer");

            return {
                ...rule,
                question,
                correctAnswer: `${question}${separator}${correctValue}`
            };
        });

        const filtered = trustyFilterService.getGameData(normalizedRules, STORAGE_KEY, timeCapMax);

        return filtered.map(item => {
            const isCorrect = Math.random() > 0.5;
            const correctValue = item.variants ? item.variants[0] : (item.answer || "No answer");
            let answerText = "";

            if (isCorrect || !item.variants || item.variants.length < 2) {
                answerText = correctValue;
            } else {
                const wrongVariants = item.variants.slice(1);
                answerText = wrongVariants[Math.floor(Math.random() * wrongVariants.length)];
            }

            return {
                ...item,
                answer: answerText,
                isCorrect: answerText === correctValue
            };
        }).sort(() => Math.random() - 0.5);
    }, [rawRules, selectedRuleIds, separator]);

    const renderStartOverlay = useCallback(() => {
        return (
            <div className={uiCss.gameOverInfo}>
                <TrustyFilterDropdown
                    title="Граматичні правила"
                    options={filterOptions}
                    selectedIds={selectedRuleIds}
                    onChange={setSelectedRuleIds}
                />
            </div>
        );
    }, [filterOptions, selectedRuleIds]);

    return (
        <TrustyGameOrchestrator
            fetchData={fetchData}
            isDoubleSet={false}
            onViewDocs={onViewDocs}
            renderStartOverlay={renderStartOverlay}
            storageKey={STORAGE_KEY}
            resetNotificationText="Ви впевнені, що хочете скинути весь прогрес вивчення правил?"
        />
    );
};

export const TrustyAllVocabGame = TrustyVocabOrchestrator;
export const TrustyRulesGame = ({ onViewDocs }) => <TrustyRulesOrchestrator onViewDocs={onViewDocs} />;
