import React from 'react';
import css from "./TagFilter.module.css";

const TagFilter = ({ availableTags, selectedFilters, onFilterChange }) => {
    if (!availableTags || availableTags.length === 0) return null;

    const toggleTag = (tag) => {
        if (selectedFilters.includes(tag) && selectedFilters.length === 1) {
            return; // Prevent deselecting the last tag
        }
        const newFilters = selectedFilters.includes(tag)
            ? selectedFilters.filter(t => t !== tag)
            : [...selectedFilters, tag];
        onFilterChange(newFilters);
    };

    return (
        <div className={css.container}>
            <h4>Фільтр за тегами</h4>
            <div className={css.tags}>
                {availableTags.map(tag => (
                    <button
                        key={tag}
                        className={`${css.tag} ${selectedFilters.includes(tag) ? css.active : ''}`}
                        onClick={() => toggleTag(tag)}
                    >
                        {tag}
                    </button>
                ))}
            </div>
        </div>
    );
};

export { TagFilter };
