import React from 'react';
import css from './DocViewer.module.css';

export const SmartTableRender = ({ data, config, mode, showTags = false }) => {
    const { hideOnStudy = [], headers = [] } = config;
    const isStudyMode = mode === 'study';

    const getCellClass = (index) => {
        if (isStudyMode && hideOnStudy.includes(index)) {
            return css.blurred;
        }
        return '';
    };

    return (
        <div className={css.smartTableContainer}>
            <table className={css.smartTable}>
                <thead>
                    <tr>
                        {headers.map((header, index) => (
                            <th key={index}>{header}</th>
                        ))}
                        {showTags && <th>Tags</th>}
                    </tr>
                </thead>
                <tbody>
                    {data.map((row) => (
                        <tr key={row.originalIndex}>
                            <td className={getCellClass(0)}>{row.v1}</td>
                            <td className={getCellClass(1)}>{row.v2}</td>
                            <td className={getCellClass(2)}>{row.v3}</td>
                            <td className={getCellClass(3)}>{row.translation}</td>
                            {showTags && (
                                <td className={css.tagsCell}>
                                    {row.tags.join(', ')}
                                </td>
                            )}
                        </tr>
                    ))}
                    {data.length === 0 && (
                        <tr>
                            <td colSpan={headers.length + (showTags ? 1 : 0)} style={{ textAlign: 'center', padding: '2rem' }}>
                                Нічого не знайдено за вашим запитом
                            </td>
                        </tr>
                    )}
                </tbody>
            </table>
        </div>
    );
};
