import { gameConfig } from '../lib/trusty.config';

const DEFAULT_STORAGE_KEY = 'trusty_word_scores';

/**
 * Сервіс адаптивної фільтрації контенту для гри «Trusty».
 */
export const trustyFilterService = {
    /**
     * Генерує унікальний ID на основі тексту (зазвичай correctAnswer).
     */
    generateHash: (text) => {
        try {
            const str = String(text || '').trim().toLowerCase();
            if (!str) return null;
            return btoa(unescape(encodeURIComponent(str)));
        } catch (e) {
            return String(text || '').replace(/[^\w]/g, '_').toLowerCase();
        }
    },

    /**
     * Отримує всі оцінки (scores) з LocalStorage.
     */
    getScores: (storageKey = DEFAULT_STORAGE_KEY) => {
        try {
            const raw = localStorage.getItem(storageKey);
            return raw ? JSON.parse(raw) : {};
        } catch (e) {
            console.warn(`[TrustyFilter] Error reading scores for key ${storageKey}`, e);
            return {};
        }
    },

    /**
     * Зберігає оцінки в LocalStorage.
     */
    saveScores: (scores, storageKey = DEFAULT_STORAGE_KEY) => {
        try {
            localStorage.setItem(storageKey, JSON.stringify(scores));
        } catch (e) {
            console.error(`[TrustyFilter] Error saving scores for key ${storageKey}`, e);
        }
    },

    /**
     * 1. Middleware: Normalization & Hashing
     */
    normalizationMiddleware: (data, storageKey = DEFAULT_STORAGE_KEY) => {
        const scores = trustyFilterService.getScores(storageKey);
        const separator = gameConfig.ui.answerSeparator;
        
        return data.map(item => {
            const hashSource = item.correctAnswer || (item.question && item.answer ? `${item.question}${separator}${item.answer}` : null);
            const hash = hashSource ? trustyFilterService.generateHash(hashSource) : null;
            
            return {
                ...item,
                id: hash || item.id,
                score: (hash && scores[hash] !== undefined) ? scores[hash] : 0
            };
        });
    },

    /**
     * 2. Middleware: Exclusion Filter
     */
    exclusionFilter: (data) => {
        return data.filter(item => {
            return item.score === undefined || item.score < 5;
        });
    },

    /**
     * 3. Middleware: Priority Filter
     */
    priorityFilter: (data) => {
        return [...data].sort((a, b) => {
            if (a.score < 0 && b.score >= 0) return -1;
            if (a.score >= 0 && b.score < 0) return 1;
            return a.score - b.score;
        });
    },

    /**
     * 4. Middleware: Capacity Filter
     * @param {Array} data - масив даних
     * @param {number} timeCapMax - максимальний час (впливає на кількість слів)
     */
    capacityFilter: (data, timeCapMax) => {
        const cap = timeCapMax || gameConfig.timing.timeCapMax || 30;
        const multiplier = gameConfig.timing.dataCapacityMultiplier || 2;
        const limit = Math.max(50, cap * multiplier); 
        return data.slice(0, limit);
    },

    /**
     * Головний метод для отримання відфільтрованих даних для гри.
     */
    getGameData: (rawData, storageKey = DEFAULT_STORAGE_KEY, timeCapMax = null) => {
        let pipeline = trustyFilterService.normalizationMiddleware(rawData, storageKey);
        
        let filtered = trustyFilterService.exclusionFilter(pipeline);
        
        if (filtered.length === 0 && rawData.length > 0) {
            console.log(`[TrustyFilter] All items learned for ${storageKey}. Entering Repetition Mode.`);
            trustyFilterService.handleEmptyState(storageKey);
            pipeline = trustyFilterService.normalizationMiddleware(rawData, storageKey);
            filtered = trustyFilterService.exclusionFilter(pipeline);
        }

        filtered = trustyFilterService.priorityFilter(filtered);
        filtered = trustyFilterService.capacityFilter(filtered, timeCapMax);

        return filtered;
    },

    /**
     * Оновлює прогрес після завершення гри.
     */
    updateProgress: (history, storageKey = DEFAULT_STORAGE_KEY) => {
        const scores = trustyFilterService.getScores(storageKey);
        
        history.forEach(entry => {
            const hash = entry.id; 
            if (!hash) return;

            const currentScore = scores[hash] || 0;

            if (entry.isUserCorrect) {
                scores[hash] = currentScore + 1;
            } else {
                scores[hash] = -2;
            }
        });

        trustyFilterService.saveScores(scores, storageKey);
    },

    /**
     * Стратегія при вичерпанні даних (Empty State Strategy).
     */
    handleEmptyState: (storageKey = DEFAULT_STORAGE_KEY) => {
        const scores = trustyFilterService.getScores(storageKey);
        const keys = Object.keys(scores);
        
        let count = 0;
        for (const key of keys) {
            if (scores[key] >= 5) {
                scores[key] = 3;
                count++;
            }
            if (count >= 30) break;
        }
        
        trustyFilterService.saveScores(scores, storageKey);
    },

    /**
     * Перевіряє, чи є взагалі якісь записи про прогрес.
     */
    hasProgress: (storageKey = DEFAULT_STORAGE_KEY) => {
        const scores = trustyFilterService.getScores(storageKey);
        return Object.keys(scores).length > 0;
    },

    /**
     * Повне очищення прогресу та рекорду.
     */
    resetProgress: (storageKey = DEFAULT_STORAGE_KEY) => {
        localStorage.removeItem(storageKey);
        localStorage.removeItem(`${storageKey}_hs`);
    }
};
