import React, { useRef, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaBook } from 'react-icons/fa';
import { useClickOutside } from '../../../../shared/hooks';
import { HoldButton } from '../../../../shared/ui';
import uiCss from './TrustyUI.module.css';

/**
 * Спеціалізований компонент для фільтрації правил у Trusty_game.
 * Підтримує множинний вибір, але візуально нагадує radio buttons.
 */
const TrustyFilterDropdown = ({
    title = "Оберіть правила",
    options = [], // [{id, name, hint, path}]
    selectedIds = [],
    onChange
}) => {
    const STORAGE_KEY_OPEN = 'trusty_filter_is_open';
    const STORAGE_KEY_EXPANDED = 'trusty_filter_expanded_hints';
    const STORAGE_KEY_SCROLL = 'trusty_filter_scroll_pos';

    // Ініціалізація стану з sessionStorage
    const [isOpen, setIsOpen] = useState(() => {
        return sessionStorage.getItem(STORAGE_KEY_OPEN) === 'true';
    });
    const [expandedHints, setExpandedHints] = useState(() => {
        const saved = sessionStorage.getItem(STORAGE_KEY_EXPANDED);
        try {
            return saved ? JSON.parse(saved) : {};
        } catch (e) {
            return {};
        }
    });

    const dropdownRef = useRef(null);
    const scrollContainerRef = useRef(null);
    const navigate = useNavigate();

    useClickOutside(dropdownRef, () => {
        setIsOpen(false);
        sessionStorage.setItem(STORAGE_KEY_OPEN, 'false');
    });

    // Зберігаємо стан при зміні
    useEffect(() => {
        sessionStorage.setItem(STORAGE_KEY_OPEN, isOpen.toString());
        
        // Відновлюємо скрол, коли меню відкривається
        if (isOpen && scrollContainerRef.current) {
            const savedScroll = sessionStorage.getItem(STORAGE_KEY_SCROLL);
            if (savedScroll) {
                // Використовуємо requestAnimationFrame для впевненості, що DOM відрендерився
                requestAnimationFrame(() => {
                    if (scrollContainerRef.current) {
                        scrollContainerRef.current.scrollTop = parseInt(savedScroll, 10);
                    }
                });
            }
        }
    }, [isOpen]);

    useEffect(() => {
        sessionStorage.setItem(STORAGE_KEY_EXPANDED, JSON.stringify(expandedHints));
    }, [expandedHints]);

    const handleScroll = (e) => {
        sessionStorage.setItem(STORAGE_KEY_SCROLL, e.target.scrollTop.toString());
    };

    const toggleDropdown = () => setIsOpen(!isOpen);

    const handleToggleOption = (id) => {
        let newSelectedIds;
        if (selectedIds.includes(id)) {
            // Запобігаємо зняттю останнього вибору, щоб гра не була порожньою
            if (selectedIds.length <= 1) return;
            newSelectedIds = selectedIds.filter(selectedId => selectedId !== id);
        } else {
            newSelectedIds = [...selectedIds, id];
        }
        onChange(newSelectedIds);
    };

    const handleToggleHint = (e, id) => {
        e.preventDefault();
        e.stopPropagation();
        setExpandedHints(prev => ({
            ...prev,
            [id]: !prev[id]
        }));
    };

    const handleOpenDoc = (e, option) => {
        e.preventDefault();
        e.stopPropagation();
        if (option.path) {
            navigate(`/doc/${option.id}`, { state: { directPath: option.path } });
        }
    };

    const selectedCount = selectedIds.length;
    const totalCount = options.length;

    const labelText = `Обрано ${selectedCount} з ${totalCount} правил`;

    return (
        <div className={uiCss.frame} ref={dropdownRef} style={{ marginBottom: '1rem' }}>
            <div className={uiCss.frameLabel}>{title}</div>
            
            <div style={{ width: '95%', margin: '0.2rem 0' }}>
                <HoldButton
                    onAction={toggleDropdown}
                    width="100%"
                    className={uiCss.dropdownTrigger}
                >
                    <div className={uiCss.dropdownTriggerContent}>
                        <span>{labelText}</span>
                        <span className={`${uiCss.arrow} ${isOpen ? uiCss.arrowOpen : ''}`}>▼</span>
                    </div>
                </HoldButton>

                {isOpen && (
                    <div 
                        className={uiCss.dropdownMenu} 
                        ref={scrollContainerRef}
                        onScroll={handleScroll}
                    >
                        <div className={uiCss.difficultyList}>
                            {options.map((option) => {
                                const isSelected = selectedIds.includes(option.id);
                                const isHintExpanded = expandedHints[option.id];
                                
                                return (
                                    <div  className={`${uiCss.rowBackground} ${isSelected ? uiCss.active : ''}`}>
                                    <label
                                        key={option.id}
                                        className={uiCss.difficultyRow}
                                        onClick={(e) => {
                                            e.preventDefault();
                                            handleToggleOption(option.id);
                                        }}
                                    >
                                        <div className={uiCss.checkboxAsRadio}>
                                            {isSelected && <div className={uiCss.radioInner} />}
                                        </div>
                                        <div className={uiCss.difficultyInfo}>
                                            <span className={uiCss.difficultyName}>{option.name}</span>
                                            
                                            <div className={uiCss.detailsToggleContainer}>
                                                <span 
                                                    className={uiCss.moreDetails}
                                                    onClick={(e) => handleToggleHint(e, option.id)}
                                                >
                                                    {isHintExpanded ? 'Сховати' : 'Докладніше'}
                                                </span>
                                            </div>


                                        </div>


                                    </label>

                                        {isHintExpanded && (
                                            <div className={uiCss.hintContentContainer}>
                                                <span className={uiCss.difficultyHint}>{option.hint}</span>
                                                {option.path && (
                                                    <FaBook
                                                        className={uiCss.docIcon}
                                                        title="Читати повну документацію"
                                                        onClick={(e) => handleOpenDoc(e, option)}
                                                    />
                                                )}
                                            </div>
                                        )}

                                    </div>

                                );
                            })}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default TrustyFilterDropdown;