import React,{ useRef, useState} from 'react';

import {appConstants} from "../../constants";


const initPosition = (key, defaultPos = {right: 0, bottom: 50}) => {
    try {
        const storedPosition = localStorage.getItem(key);
        if (storedPosition) {
            return JSON.parse(storedPosition);
        }
    } catch (error) {
        console.error("Failed to parse position from localStorage:", error);
    }
    return defaultPos;
}

const Draggable = ({onAction, offAction, onEnter, children, storageKey, ...otherProps}) => {

    const {positionYUpdateThreshold} = appConstants
    const storageKeyToUse = storageKey || "draggable-position";
    const [position, setPosition] = useState(initPosition(storageKeyToUse));


    const isDraggingRef = useRef(false);
    const latestPositionRef = useRef(position)
    const dragRef = useRef(null);
    const offset = useRef({x: 0, y: 0});

    const handlePointerDown = (event) => {
        isDraggingRef.current = true;
        if (typeof onAction === "function") onAction();
        event.target.setPointerCapture(event.pointerId);
        offset.current = {
            x: event.clientX - (window.innerWidth - position.right),
            y: event.clientY - (window.innerHeight - position.bottom)
        };
    };

    const handlePointerMove = (event) => {
        if (isDraggingRef.current) {
            const newRight = Math.max(0, Math.min(window.innerWidth - event.clientX + offset.current.x, window.innerWidth - 50));
            const newBottom = Math.max(0, Math.min(window.innerHeight - event.clientY + offset.current.y, window.innerHeight - 50));

            if (Math.abs(position.right - newRight) > positionYUpdateThreshold || Math.abs(position.bottom - newBottom) > positionYUpdateThreshold) {
                const newPosition = {right: newRight, bottom: newBottom};
                latestPositionRef.current = newPosition;
                setPosition(newPosition);
            }
        }
    };

    const handlePointerUp = (event) => {
        isDraggingRef.current = false;
        if (typeof offAction === "function") offAction();
        event.target.releasePointerCapture(event.pointerId);
        
        const newRight = Math.max(0, Math.min(window.innerWidth - event.clientX + offset.current.x, window.innerWidth - 50));
        const newBottom = Math.max(0, Math.min(window.innerHeight - event.clientY + offset.current.y, window.innerHeight - 50));
        const newPosition = {right: newRight, bottom: newBottom};
        
        latestPositionRef.current = newPosition;
        setPosition(newPosition);
        try {
            localStorage.setItem(storageKeyToUse, JSON.stringify(newPosition));
        } catch (error) {
            console.error("Failed to save position to localStorage:", error);
        }
    };

    const handlePointerCancel = (event) => {
        isDraggingRef.current = false;
        if (typeof offAction === "function") offAction();
        event.target.releasePointerCapture(event.pointerId);
    };

    const handlePointerEnter = () => {
        if (typeof onEnter == "function") onEnter();
    };

    const handlePointerLeave = () => {
        if (typeof offAction === "function") offAction()
    };

    return (
        <div
            ref={dragRef}
            onPointerEnter={handlePointerEnter}
            onPointerLeave={handlePointerLeave}
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onPointerCancel={handlePointerCancel}

            style={{
                userSelect: 'none',
                touchAction: 'none',
                position: "fixed",
                zIndex: "1000",
                right: position.right,
                bottom: position.bottom,
                cursor: isDraggingRef.current ? 'grabbing' : 'grab',
            }}
            {...otherProps}
        >
            {children}
        </div>
    )
};

export {Draggable};