
const STORAGE_PREFIX = 'tagFilters_';

export const getStoredFilters = (lessonId) => {
    try {
        const stored = localStorage.getItem(`${STORAGE_PREFIX}${lessonId}`);
        return stored ? JSON.parse(stored) : [];
    } catch (e) {
        console.error("Error loading filters:", e);
        return [];
    }
};

export const saveFilters = (lessonId, filters) => {
    localStorage.setItem(`${STORAGE_PREFIX}${lessonId}`, JSON.stringify(filters));
};

export const extractTags = (scenarioItems) => {
    const tags = new Set();
    if (!Array.isArray(scenarioItems)) return [];
    scenarioItems.forEach(item => {
        if (item && item.tags && Array.isArray(item.tags)) {
            item.tags.forEach(tag => tags.add(tag));
        }
    });
    return Array.from(tags).sort();
};

export const filterItems = (scenarioItems, selectedFilters) => {
    if (!selectedFilters || selectedFilters.length === 0) {
        return scenarioItems;
    }

    return scenarioItems.filter(item => {
        if (!item.tags || !Array.isArray(item.tags) || item.tags.length === 0) {
            return false; // Items without tags are filtered out if any filter is active, 
                          // as per requirement for specific tag-based filtering.
                          // If 'No Tags' is required, it should be a specific tag in UI.
        }
        return item.tags.some(tag => selectedFilters.includes(tag));
    });
};
