import React from 'react';
import { DocTreeBrowser } from '../features/DocViewer';
import { useDocTree } from '../app/hooks/useDocTree';

const DocTreePage = () => {
    const { tree, isLoading, error } = useDocTree();

    return (
        <div style={{ padding: '20px' }}>
            <DocTreeBrowser tree={tree} isLoading={isLoading} error={error} />
        </div>
    );
};

export { DocTreePage };
