import {useMediaQuery, appConstants} from "../../shared";


const useResponsiveMode = () => {
    const { breakpoints } = appConstants;
    const isMobile = useMediaQuery(`(max-width: ${breakpoints.mobile}px)`);
    const isTablet = useMediaQuery(`(min-width: ${breakpoints.mobile + 0.1}px) and (max-width: ${breakpoints.tablet}px)`);
    const isDesktop = useMediaQuery(`(min-width: ${breakpoints.tablet + 0.1}px)`);
    
    if (isMobile) {
        return {mode: "mobile", rate: 1}
    } else if (isTablet) {
        return {mode: "tablet", rate: 1}
    } else if (isDesktop) {
        return {mode: "desktop", rate: 1}
    }
}

export {useResponsiveMode}