import React, {useState, useCallback, useEffect, useMemo} from 'react';
import {TrustyProvider} from './TrustyProvider';
import {TrustyGame} from './TrustyGame';
import TrustyRadioSelector from './TrustyUI/TrustyRadioSelector';
import {HoldButton, Odometer} from '../../../shared/ui';
import {TrustyResultsReview} from './TrustyResultsReview';
import {trustyFilterService} from '../services/trustyFilterService';
import {notificationService} from '../../../shared/lib/notification/notification';
import {gameConfig} from '../lib/trusty.config';

import css from './TrustyGame.module.css';
import uiCss from './TrustyUI/TrustyUI.module.css';

// Константи порогів для збереження прогресу
const THRESHOLDS = {
    easy: -1,
    medium: 70,
    hard: 90
};

// Конфігурації складності
const DIFFICULTY_CONFIGS = {
    easy: {
        timing: {...gameConfig.timing, timePerWord: 2, timeCapMax: 60},
        scoring: {...gameConfig.scoring, timeStreakBonusMap: {1: 4, 2: 3, 3: 2, 10: 5, 20: 10}, streakBonusMap: {}}
    },
    medium: {
        timing: {...gameConfig.timing, timePerWord: 1, timeCapMax: 30},
        scoring: {...gameConfig.scoring, pointsPerCorrect: 2}
    },
    hard: {
        timing: {...gameConfig.timing, timePerWord: 0.6, timeCapMax: 20},
        scoring: {...gameConfig.scoring, pointsPerCorrect: 3}
    }
};

/**
 * TrustyGameOrchestrator - керує життєвим циклом гри.
 */
export const TrustyGameOrchestrator = ({
                                           fetchData,
                                           isDoubleSet = true,
                                           onNextRoundRequest,
                                           onViewDocs,
                                           renderStartOverlay,
                                           startButtonLabel = "Почати",
                                           storageKey = "trusty_word_scores",
                                           resetNotificationText = "Ви впевнені, що хочете скинути весь прогрес?"
                                       }) => {
    const SESSION_KEY = useMemo(() => `trusty_session_${storageKey}`, [storageKey]);

    const savedState = useMemo(() => {
        try {
            const saved = sessionStorage.getItem(SESSION_KEY);
            return saved ? JSON.parse(saved) : null;
        } catch (e) {
            return null;
        }
    }, [SESSION_KEY]);

    const [step, setStep] = useState(savedState?.step || 'CHOICE'); // CHOICE, PLAYING, INTERMEDIATE, RESULTS
    const [round, setRound] = useState(savedState?.round || 1);
    const [difficulty, setDifficulty] = useState(savedState?.difficulty || 'medium');

    const [round1Score, setRound1Score] = useState(savedState?.round1Score || 0);
    const [round2Score, setRound2Score] = useState(savedState?.round2Score || 0);
    const [round1History, setRound1History] = useState(savedState?.round1History || []);
    const [round2History, setRound2History] = useState(savedState?.round2History || []);

    const [currentData, setCurrentData] = useState(savedState?.currentData || []);
    const [demoData, setDemoData] = useState([]);
    const [showHistory, setShowHistory] = useState(savedState?.showHistory || false);
    const [progressExists, setProgressExists] = useState(trustyFilterService.hasProgress(storageKey));

    // Збереження стану в сесію при змінах
    useEffect(() => {
        const stateToSave = {
            step, round, difficulty,
            round1Score, round2Score,
            round1History, round2History,
            showHistory, currentData
        };
        sessionStorage.setItem(SESSION_KEY, JSON.stringify(stateToSave));
    }, [SESSION_KEY, step, round, difficulty, round1Score, round2Score, round1History, round2History, showHistory, currentData]);

    // Динамічний ключ для High Score
    const highScoreKey = useMemo(() => `${storageKey}_hs`, [storageKey]);

    // Отримання поточного рекорду для ініціалізації
    const currentHighScore = useMemo(() => {
        const saved = localStorage.getItem(highScoreKey);
        return saved ? parseInt(saved, 10) : 0;
    }, [highScoreKey, step]);

    const currentScoringConfig = useMemo(() => DIFFICULTY_CONFIGS[difficulty], [difficulty]);

    useEffect(() => {
        if (step === 'CHOICE') {
            setProgressExists(trustyFilterService.hasProgress(storageKey));
        }
    }, [step, storageKey]);

    useEffect(() => {
        if (demoData.length === 0 && step === 'CHOICE' && fetchData) {
            try {
                // Використовуємо дефолтну складність (medium) для демо
                const data = fetchData(DIFFICULTY_CONFIGS.medium.timing.timeCapMax);
                setDemoData(data);
            } catch (e) {
                console.warn("[TrustyOrchestrator] Demo load error:", e);
            }
        }
    }, [demoData.length, step, fetchData]);

    const handleStart = useCallback(() => {
        const data = fetchData(currentScoringConfig.timing.timeCapMax);
        setCurrentData(data);
        setStep('PLAYING');
        setRound(1);
    }, [fetchData, currentScoringConfig]);

    const handleSessionComplete = useCallback((score, history) => {
        if (step !== 'PLAYING') return;

        // Збереження прогресу за порогами (крім Easy)
        if (difficulty !== 'easy') {
            const correctCount = history.filter(item => item.isUserCorrect).length;
            const totalCount = history.length;
            const successRate = totalCount > 0 ? (correctCount / totalCount) * 100 : 0;
            const threshold = THRESHOLDS[difficulty];

            if (successRate >= threshold) {
                trustyFilterService.updateProgress(history, storageKey);
            } else {
                notificationService.info(`Успіх ${successRate.toFixed(0)}% (потрібно ${threshold}% для збереження прогресу)`);
            }
        }

        if (round === 1) {
            setRound1Score(score);
            setRound1History(history);
            if (isDoubleSet) {
                setStep('INTERMEDIATE');
            } else {
                setStep('RESULTS');
                saveFinalHighScore(score);
            }
        } else {
            setRound2Score(score);
            setRound2History(history);
            setStep('RESULTS');
            const finalScore = Math.round((round1Score + score) / 2);
            saveFinalHighScore(finalScore);
        }
    }, [round, isDoubleSet, round1Score, step, difficulty, storageKey]);

    const saveFinalHighScore = (finalScore) => {
        // Режим Easy не приймає участі в рекордах
        if (difficulty === 'easy') return;

        const savedHS = localStorage.getItem(highScoreKey);
        if (!savedHS || finalScore > parseInt(savedHS, 10)) {
            localStorage.setItem(highScoreKey, String(finalScore));
            if (savedHS) notificationService.success("Новий рекорд встановлено!");
        }
    };

    const handleNextRound = useCallback(() => {
        const nextData = onNextRoundRequest ? onNextRoundRequest(currentData) : currentData;
        setCurrentData(nextData);
        setRound(2);
        setStep('PLAYING');
        setShowHistory(false);
    }, [currentData, onNextRoundRequest]);

    const handleRetry = () => {
        sessionStorage.removeItem(SESSION_KEY);
        setStep('CHOICE');
        setRound1Score(0);
        setRound2Score(0);
        setRound1History([]);
        setRound2History([]);
        setShowHistory(false);
        setCurrentData([]);
    };

    const handleReset = () => {
        notificationService.warning(
            resetNotificationText,
            0,
            [
                {
                    label: "Так, скинути",
                    callback: () => {
                        sessionStorage.removeItem(SESSION_KEY);
                        trustyFilterService.resetProgress(storageKey);
                        const data = fetchData();
                        setDemoData(data);
                        setProgressExists(false);
                        notificationService.success("Прогрес успішно скинуто");
                    }
                },
                {
                    label: "Ні, залишити",
                    callback: () => {
                    }
                }
            ]
        );
    };

    const renderOverlay = () => {
        if (step === 'CHOICE') {
            const difficultyOptions = [
                {
                    id: 'easy',
                    name: 'Навчання (Easy)',
                    hint: 'Для ознайомлення. Прогрес та рекорди не записуються.'
                },
                {
                    id: 'medium',
                    name: 'Тренування (Medium)',
                    hint: `Збереження прогресу від ${THRESHOLDS.medium}%.`
                },
                {
                    id: 'hard',
                    name: 'Екзамен (Hard)',
                    hint: `Збереження прогресу від ${THRESHOLDS.hard}%.`
                }
            ];

            return (
                <div className={css.overlay}>
                    <div className={css.mainArea}>
                        {renderStartOverlay && renderStartOverlay()}
                        
                        <div className={uiCss.gameOverInfo}>
                            <TrustyRadioSelector
                                title="Оберіть складність"
                                options={difficultyOptions}
                                value={difficulty}
                                onChange={setDifficulty}
                                direction="column"
                            />

                            <div className={uiCss.actionsContainer}
                                 style={{flexDirection: 'column', gap: '1rem', marginTop: '1.5rem', width: '100%', padding: 0}}>
                                <HoldButton onAction={handleStart} className={uiCss.actionBtn} style={{width: "100%"}}>
                                    {startButtonLabel}
                                </HoldButton>

                                {progressExists && (
                                    <HoldButton
                                        onAction={handleReset}
                                        className={`${uiCss.actionBtn} ${uiCss.exitBtn}`}
                                        style={{width: "100%", opacity: 0.7}}
                                    >
                                        Скинути прогрес
                                    </HoldButton>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            );
        }
        if (step === 'INTERMEDIATE') {
            return (
                <div className={css.overlay}>
                    <div className={css.mainArea} style={{overflowY: 'auto'}}>
                        {showHistory ? (
                            <TrustyResultsReview history={round1History} onViewDocs={onViewDocs}/>
                        ) : (
                            <div className={uiCss.gameOverInfo} style={{justifyContent: 'center', height: '100%'}}>
                                <h2>Сет 1 завершено!</h2>
                                <div className={uiCss.stats}>
                                    <div className={uiCss.statRow}>
                                        <span>Ваш бал:</span>
                                        <Odometer number={round1Score}/>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                    <div className={css.footerArea}>
                        <div className={uiCss.actionsContainer}>
                            <HoldButton
                                onAction={() => setShowHistory(!showHistory)}
                                className={`${uiCss.actionBtn} ${uiCss.reviewBtn}`}
                            >
                                {showHistory ? "До результатів" : "Переглянути історію"}
                            </HoldButton>
                            {!showHistory && (
                                <HoldButton onAction={handleNextRound} className={uiCss.actionBtn}>
                                    Перейти до Сету 2
                                </HoldButton>
                            )}
                        </div>
                    </div>
                </div>
            );
        }

        if (step === 'RESULTS') {
            const finalScore = isDoubleSet ? Math.round((round1Score + round2Score) / 2) : round1Score;
            return (
                <div className={css.overlay}>
                    <div className={css.mainArea} style={{overflowY: 'auto'}}>
                        {showHistory ? (
                            <TrustyResultsReview history={[...round1History, ...round2History]} onViewDocs={onViewDocs}/>
                        ) : (
                            <div className={uiCss.gameOverInfo} style={{justifyContent: 'center', height: '100%'}}>
                                <h2>Гру завершено!</h2>
                                <div className={uiCss.stats}>
                                    <div className={uiCss.statRow}>
                                        <span>Сет 1:</span>
                                        <Odometer number={round1Score}/>
                                    </div>
                                    {isDoubleSet && (
                                        <div className={uiCss.statRow}>
                                            <span>Сет 2:</span>
                                            <Odometer number={round2Score}/>
                                        </div>
                                    )}
                                    <div className={uiCss.statRow}
                                         style={{fontWeight: 'bold', borderTop: '2px solid var(--border-color)'}}>
                                        <span>Підсумковий бал:</span>
                                        <Odometer number={finalScore}/>
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                    <div className={css.footerArea}>
                        <div className={uiCss.actionsContainer}>
                            <HoldButton
                                onAction={() => setShowHistory(!showHistory)}
                                className={`${uiCss.actionBtn} ${uiCss.reviewBtn}`}
                            >
                                {showHistory ? "До результатів" : "Аналіз всієї гри"}
                            </HoldButton>
                            {!showHistory && (
                                <>
                                    <HoldButton onAction={handleRetry} className={uiCss.actionBtn}>
                                        Спробувати ще раз
                                    </HoldButton>
                                    <HoldButton onAction={() => window.location.reload()}
                                                className={`${uiCss.actionBtn} ${uiCss.exitBtn}`}>
                                        Вихід
                                    </HoldButton>
                                </>
                            )}
                        </div>
                    </div>
                </div>
            );
        }

        return null;
    };

    const isPlaying = step === 'PLAYING';
    const activeData = isPlaying ? currentData : demoData;

    return (
        <div className={css.managerContainer}>
            <div className={`${css.gameBackground} ${!isPlaying ? css.frozen : ''}`}>
                {activeData.length > 0 && (
                    <TrustyProvider
                        data={activeData}
                        key={`${round}-${isPlaying ? 'active' : 'demo'}-${difficulty}-${highScoreKey}`}
                        config={currentScoringConfig}
                        initialHighScore={currentHighScore}
                    >
                        <TrustyGame
                            data={activeData}
                            onComplete={handleSessionComplete}
                            isDemo={!isPlaying}
                        />
                    </TrustyProvider>
                )}
            </div>
            {renderOverlay()}
        </div>
    );
};

// Alias for backward compatibility
export const TrustyGameManager = TrustyGameOrchestrator;
