import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { MdChevronRight, MdExpandMore, MdDescription, MdFolder } from 'react-icons/md';
import css from './DocTreeBrowser.module.css';

const TreeNode = ({ node }) => {
    const [isExpanded, setIsExpanded] = useState(false);
    const hasChildren = node.children && node.children.length > 0;

    const handleToggle = (e) => {
        if (hasChildren) {
            e.preventDefault();
            setIsExpanded(!isExpanded);
        }
    };

    return (
        <div className={css.nodeWrapper}>
            <div 
                className={`${css.nodeHeader} ${hasChildren ? css.clickable : ''}`} 
                onClick={handleToggle}
            >
                {hasChildren && (
                    <span className={css.toggleIcon}>
                        {isExpanded ? <MdExpandMore /> : <MdChevronRight />}
                    </span>
                )}
                <span className={css.typeIcon}>
                    {hasChildren ? <MdFolder className={css.folderIcon} /> : <MdDescription className={css.fileIcon} />}
                </span>
                
                {node.path ? (
                    <Link to={`/doc/${node.id}`} className={css.nodeLink}>
                        {node.title || node.id}
                    </Link>
                ) : (
                    <span className={css.nodeTitle}>{node.title || node.id}</span>
                )}
            </div>

            {hasChildren && isExpanded && (
                <div className={css.childrenContainer}>
                    {node.children.map(child => (
                        <TreeNode key={child.id} node={child} />
                    ))}
                </div>
            )}
        </div>
    );
};

export const DocTreeBrowser = ({ tree, isLoading, error }) => {
    if (isLoading) return <div className={css.loading}>Завантаження структури...</div>;
    
    if (error) {
        return (
            <div className={css.error}>
                <h2>Помилка завантаження</h2>
                <p>{error}</p>
                <p>Перевірте наявність файлу <code>public/configs/docs.doctree</code></p>
            </div>
        );
    }

    if (!tree || tree.length === 0) {
        return <div className={css.empty}>Структура документації порожня або невірна.</div>;
    }

    return (
        <div className={css.treeBrowser}>
            <h1>Зміст документації</h1>
            <div className={css.treeRoot}>
                {tree.map(node => (
                    <TreeNode key={node.id} node={node} />
                ))}
            </div>
        </div>
    );
};
