/**
 * Парсить Markdown контент для виявлення та обробки Smart Table.
 * @param {string} rawMd - Сирий текст Markdown файлу.
 * @returns {object|null} - Об'єкт з config та data, або null, якщо це не Smart Table.
 */
export const parseSmartTable = (rawMd) => {
    // Підтримка як --- так і === (Jekyll ігнорує ===)
    const metaRegex = /^(---\n|===\n)([\s\S]*?)\n\1/;
    const match = rawMd.match(metaRegex);

    if (!match) return null;

    const metaPart = match[2]; // match[1] - це роздільник, match[2] - контент
    const contentPart = rawMd.replace(metaRegex, '').trim();

    // Парсинг конфігурації (підтримка об'єктів та масивів)
    const config = {};
    const lines = metaPart.trim().split('\n');
    let currentKey = null;
    let currentValueStr = '';

    const parseValue = (val) => {
        val = val.trim();
        if ((val.startsWith('[') && val.endsWith(']')) || (val.startsWith('{') && val.endsWith('}'))) {
            try {
                // Замінюємо одинарні лапки на подвійні для JSON.parse, якщо вони є
                const jsonVal = val.replace(/'/g, '"');
                return JSON.parse(jsonVal);
            } catch (e) {
                console.error('Error parsing JSON in config:', val);
                return val;
            }
        }
        if (!isNaN(val) && val !== '') return Number(val);
        return val;
    };

    lines.forEach(line => {
        const colonIndex = line.indexOf(':');
        // Якщо рядок починається з ключа (має двокрапку і не є частиною JSON об'єкта)
        if (colonIndex !== -1 && !line.trim().startsWith('{') && !line.trim().startsWith('"')) {
            if (currentKey) {
                config[currentKey] = parseValue(currentValueStr);
            }
            currentKey = line.substring(0, colonIndex).trim();
            currentValueStr = line.substring(colonIndex + 1).trim();
        } else {
            currentValueStr += ' ' + line.trim();
        }
    });
    if (currentKey) {
        config[currentKey] = parseValue(currentValueStr);
    }

    if (config.type !== 'smart-table') return null;

    // Парсинг рядків таблиці
    const contentLines = contentPart.split('\n');
    const tableRows = contentLines.filter(line => line.includes('|') && !line.includes('---|'));
    
    if (tableRows.length < 2) return { config, data: [] };

    // Зберігаємо заголовки (перший рядок)
    const headerRow = tableRows[0].split('|')
        .filter((_, i, arr) => i > 0 && i < arr.length - 1)
        .map(cell => cell.trim());

    // Пропускаємо заголовок (перший рядок)
    const dataRows = tableRows.slice(1);

    const data = dataRows.map((row, index) => {
        const cells = row.split('|')
            .filter((_, i, arr) => i > 0 && i < arr.length - 1) // Ігноруємо порожні елементи від крайових пайпів
            .map(cell => cell.trim());

        const tagsIndex = config.tagsCol !== undefined ? config.tagsCol : 4;

        return {
            v1: cells[0] || '',
            v2: cells[1] || '',
            v3: cells[2] || '',
            translation: cells[3] || '',
            tags: cells[tagsIndex] ? cells[tagsIndex].split(',').map(t => t.trim()) : [],
            originalIndex: index
        };
    });

    return { config, data, headers: headerRow };
};
