import React, {useEffect, useRef, useState} from 'react';
import {useMainState} from "../MainStateMachineProvider";
import {Frame} from "../Frame/Frame";
import {ScenarioSettingsModal} from "../ScenarioSettings/ScenarioSettingsModal";
import {machine as m} from "../../constants/machine.constants";
import {Draggable} from "../../../../shared/ui/Draggable/Draggable";

import css from "./FrameManager.module.css"

const FrameManager = () => {

    const state = useMainState();
    const lastItemRef = useRef(null);
    
    // Safely extract dependencies for useEffect
    const {
        currentCardIndex = 0, 
        currentScenarioIndex = 0,
    } = state?.context || {};

    const [isSettingsOpen, setIsSettingsOpen] = useState(false);

    useEffect(() => {
        if (lastItemRef.current) {
            lastItemRef.current.scrollIntoView({behavior: "smooth"});
        }
    }, [currentScenarioIndex, currentCardIndex]);

    const {
        currentIndex = 0,
        data = [],
        scenario = []
    } = state.context || {};
    // console.log(">>>>: ",state.context[0]);
    const filteredItems = data[currentIndex]?.scenarioItems || [];
    const title = data[currentIndex]?.title || "";


    const renderFrames = ({scenario, item, cardTextNumber, index}) => {
        return (
            <div key={item.id} className={css.card}>
                {index <= currentCardIndex && <div className={css.badge}>{cardTextNumber}</div>}
                {scenario.map(s => (
                    <Frame
                        key={s.id}
                        dataItem={item}
                        // cardIndex={item.id}
                        cardIndex={index}
                        scenarioIndex={s.id}
                        currentScenario={s}
                        currentCardIndex={currentCardIndex}
                        currentScenarioIndex={currentScenarioIndex}
                    />
                ))}
            </div>
        );
    }


    return (
        <>
            {(state.matches(m.state.idle) || state.matches(m.state.paused)) && (
                <Draggable storageKey="settings-icon-position">
                    <button 
                        onClick={() => setIsSettingsOpen(true)}
                        style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: '24px' }}
                    >
                        ⚙️
                    </button>
                </Draggable>
            )}
            <ScenarioSettingsModal 
                isVisible={isSettingsOpen} 
                onClose={() => setIsSettingsOpen(false)}
            />
            {title && <div className={css.text}>{title}</div>}
            <div>
                {filteredItems && scenario && filteredItems.map((item, index) => (renderFrames({
                    scenario,
                    item,
                    cardTextNumber: `${index + 1}/${filteredItems.length}`,
                    index
                })))}
            </div>
            <div ref={lastItemRef}></div>
        </>
    );
};

export {FrameManager};
