import React from 'react';
import { useTrustyState } from '../TrustyProvider';
import { trustyConstants as c } from '../../lib/trusty.constants';
import { Odometer } from '../../../../shared/ui';
import css from './TrustyUI.module.css';

/**
 * UIContent відображає контентну частину двигуна (результати раунду).
 */
export const UIContent = () => {
    const state = useTrustyState();
    
    // Стан для анімованих значень (починаємо з 0)
    const [animatedScores, setAnimatedScores] = React.useState({
        score: 0,
        highScore: 0
    });

    const { score, highScore } = state.context;
    const isGameOver = state.matches(c.states.gameOver);

    // Ефект для запуску анімації одометра
    React.useEffect(() => {
        if (isGameOver) {
            // Спочатку скидаємо в 0
            setAnimatedScores({ score: 0, highScore: 0 });
            
            // Через невелику паузу встановлюємо фінальні значення, що запустить прокрутку
            const timer = setTimeout(() => {
                setAnimatedScores({
                    score: state.context.score,
                    highScore: state.context.highScore
                });
            }, 100);
            return () => clearTimeout(timer);
        }
    }, [isGameOver, score, highScore]);

    if (isGameOver) {
        return (
            <div className={css.gameOverInfo}>
                {/*<div className="bage">UIContent</div>*/}
                <h2>Раунд завершено!</h2>
                <div className={css.stats}>
                    <div className={css.statRow}>
                        <span>Ваш бал:</span>
                        <Odometer number={animatedScores.score} />
                    </div>
                    <div className={css.statRow}>
                        <span>Рекорд:</span>
                        <Odometer number={animatedScores.highScore} />
                    </div>
                </div>
                {score > highScore && <div className={css.newRecord}>НОВИЙ РЕКОРД!</div>}
            </div>
        );
    }

    return null;
};
