import React, {useState, useRef, useEffect} from 'react';
import {Link} from 'react-router-dom';
import {MdKeyboardArrowDown, MdLock, MdChevronLeft} from 'react-icons/md';
import {useNavLinksConfig} from "../../config/menuNavLinks.config";
import {useResponsiveMode} from "../../hooks/useResponsiveMode";
import {appConstants} from "../../../shared";
import css from './Sidebar.module.css';

const DropdownMenu = ({item, isCollapsed, isOpen, onToggle}) => {
    const dropdownRef = useRef(null);

    useEffect(() => {
        if (dropdownRef.current) {
            dropdownRef.current.style.height = isOpen && !isCollapsed ? `${dropdownRef.current.scrollHeight}px` : '0';
        }
    }, [isOpen, isCollapsed]);

    const Icon = item.icon;

    return (
        <li className={`${css.navItem} ${isOpen ? css.open : ''}`}>
            <button className={css.navLink} onClick={onToggle}>
                {Icon && <span className={css.navIcon}><Icon /></span>}
                <span className={css.navLabel}>{item.title}</span>
                <span className={css.dropdownIcon}>
                    <MdKeyboardArrowDown/>
                </span>
            </button>
            <ul className={css.dropdownMenu} ref={dropdownRef}>
                <li className={css.navItem}>
                    <span className={`${css.navLink} ${css.dropdownTitle}`}>{item.title}</span>
                </li>
                {item.children?.map((child, index) => {
                    if (child.component) {
                        const Component = child.component;
                        return (
                            <li key={index} className={css.navItem}>
                                <div className={css.navLink}>
                                    <Component {...child.props} />
                                </div>
                            </li>
                        );
                    }
                    return (
                        <li key={index} className={css.navItem}>
                            <Link to={child.path || '#'} className={css.navLink}>
                                <span className={css.navLabel}>{child.title}</span>
                            </Link>
                        </li>
                    );
                })}
            </ul>
        </li>
    );
};

const Sidebar = ({isOpen: mobileOpen, setIsOpen: setMobileOpen}) => {
    const {mode} = useResponsiveMode();
    const navLinks = useNavLinksConfig();
    const [isCollapsed, setIsCollapsed] = useState(mode !== 'desktop');
    const [openDropdown, setOpenDropdown] = useState(null);
    const [isLocked, setIsLocked] = useState(false);
    const [isResizing, setIsResizing] = useState(false);

    // Track the last mode to detect changes
    const [lastMode, setLastMode] = useState(mode);

    if (mode !== lastMode) {
        setLastMode(mode);
        if (!isLocked) {
            setIsCollapsed(mode !== 'desktop');
        }
    }

    const isEffectiveCollapsed = isCollapsed && !isLocked && mode !== 'mobile';

    const handleDropdownToggle = (title) => {
        setOpenDropdown(prev => (prev === title ? null : title));
    };

    const handleTogglerClick = () => {
        setOpenDropdown(null);
        setIsResizing(true);
        setIsCollapsed(!isCollapsed);
        setTimeout(() => setIsResizing(false), 300);
    };

    const handleLockClick = () => {
        setIsLocked(prev => !prev);
        if (!isLocked) setIsCollapsed(false);
    };

    const primaryNavItems = navLinks.filter(item => item.group !== "footer");
    const footerNavItems = navLinks.filter(item => item.group === "footer");

    const {sidebarWidths} = appConstants;
    const sidebarStyle = {
        '--_sidebar-width': mode === 'mobile' ? sidebarWidths.mobile : sidebarWidths.expanded,
        '--_sidebar-width-collapsed': sidebarWidths.collapsed
    };

    return (
        <>
            <aside 
                className={[
                    css.sidebar,
                    css[mode],
                    isEffectiveCollapsed ? css.collapsed : '',
                    isLocked ? css.locked : '',
                    mobileOpen ? css.mobileOpen : '',
                    isResizing ? css.resizing : ''
                ].join(' ').trim()}
                style={sidebarStyle}
            >
                {mode !== 'mobile' && (
                    <header className={css.sidebarHeader}>
                        <button
                            className={`${css.sidebarLockButton} ${isLocked ? css.activeLock : ''}`}
                            onClick={handleLockClick}
                            title="Lock Sidebar"
                        >
                            <MdLock/>
                        </button>
                        <button
                            className={`${css.sidebarToggler} ${isLocked ? css.disabled : ''}`}
                            onClick={handleTogglerClick}
                            disabled={isLocked}
                        >
                            <span style={{transform: isCollapsed ? 'rotate(180deg)' : 'none', display: 'flex'}}>
                                <MdChevronLeft/>
                            </span>
                        </button>
                    </header>
                )}

                <nav className={css.sidebarNav}>
                    <ul className={`${css.navList} ${css.primaryNav}`}>
                        {primaryNavItems.map((item, index) => {
                            const Icon = item.icon;
                            if (item.children) {
                                return (
                                    <DropdownMenu
                                        key={index}
                                        item={item}
                                        isCollapsed={isEffectiveCollapsed}
                                        isOpen={openDropdown === item.title}
                                        onToggle={() => handleDropdownToggle(item.title)}
                                    />
                                );
                            }
                            return (
                                <li key={index} className={css.navItem}>
                                    {item.action ? (
                                        <button onClick={item.action} className={css.navLink}>
                                            {Icon && <span className={css.navIcon}><Icon /></span>}
                                            <span className={css.navLabel}>{item.title}</span>
                                        </button>
                                    ) : (
                                        <Link to={item.path || '#'} className={css.navLink}>
                                            {Icon && <span className={css.navIcon}><Icon /></span>}
                                            <span className={css.navLabel}>{item.title}</span>
                                        </Link>
                                    )}
                                </li>
                            );
                        })}
                    </ul>

                    <div className={css.settingsSection}>
                        <ul className={css.navList}>
                            {footerNavItems.map((item, index) => (
                                <DropdownMenu
                                    key={index}
                                    item={item}
                                    isCollapsed={isEffectiveCollapsed}
                                    isOpen={openDropdown === item.title}
                                    onToggle={() => handleDropdownToggle(item.title)}
                                />
                            ))}
                        </ul>
                    </div>
                </nav>
            </aside>
        </>
    );
};

export {Sidebar};
