import React, { useEffect } from 'react';
import { useTrustyActor, useTrustyState } from './TrustyProvider';
import { trustyConstants as c } from '../lib/trusty.constants';
import { TrustyUI } from './TrustyUI/TrustyUI';
import { TrustyGameItem } from './TrustyGameItem/TrustyGameItem';

import css from './TrustyGame.module.css';

/**
 * TrustyGame - це двигун (Round Runner).
 */
export const TrustyGame = ({ data, onComplete, isDemo = false }) => {
    const { send } = useTrustyActor();
  const state = useTrustyState();

  // Перший запуск: завантаження даних
  useEffect(() => {
    if (data && data.length > 0) {
      send({ type: c.events.START, data });
    }
  }, [send, data]);

  // Автоматично переходимо з ready в playing
  useEffect(() => {
    if (state.matches(c.states.ready)) {
      send({ type: c.events.START });
    }
  }, [state.value, send]);

  // Колбек завершення раунду
  useEffect(() => {
    if (state.matches(c.states.gameOver) && onComplete) {
      onComplete(state.context.score, state.context.history);
    }
  }, [state.value, onComplete, state.context.score, state.context.history]);

  const isIdle = state.matches(c.states.idle);
  const isPlaying = state.matches(c.states.playing) || state.matches(c.states.paused);
  const isPaused = state.matches(c.states.paused);

  if (isIdle) return <div className={css.loading}>Підготовка...</div>;

  // Візуальна структура ігрової зони
  const gameView = (
    <div className={css.gameArea}>
        <TrustyGameItem />
    </div>
  );

  // В режимі ДЕМО повертаємо повний вигляд гри, але без інтерактиву
  if (isDemo) {
      return (
          <div className={css.container}>
              <div className={css.mainArea}>
                {gameView}
              </div>
              <div className={css.footerArea}>
                 <TrustyUI mode="playing" isDemo={true} />
              </div>
          </div>
      );
  }

  return (
    <div className={css.container}>
      <div className={css.mainArea}>
        {isPlaying ? gameView : (
          <div className={css.gameOverContent}>
             <TrustyUI mode="content" />
          </div>
        )}
      </div>
      <div className={css.footerArea}>
        <TrustyUI mode={isPlaying ? (isPaused ? "paused" : "playing") : "actions"} />
      </div>
    </div>
  );
};
