import { appConstants } from '../../../shared/constants/appConstants';
import defaultData from '../data/defaultData.json';
import defaultRules from '../data/defaultRules.json';
import defaultRulesMeta from '../data/defaultRulesMeta.json';

export const dataManagerService = {
    /**
     * Отримує всі доступні слова (Vocab All).
     */
    fetchAllVocab: () => {
        const items = dataManagerService.filterItemsByType(appConstants.scenarioItemTypeVocabulary);
        return items.length > 0 ? items : defaultData;
    },

    /**
     * Отримує дані для гри "Правила" (Rules).
     */
    fetchRulesData: () => {
        const rulesType = appConstants.scenarioItemTypeRules || "rules"; 
        
        // 1. Спробуємо знайти дані нового формату (прямий масив у rwd_data_trusty_rules)
        try {
            const rawTrustyRules = localStorage.getItem(appConstants.localStorageDataPrefix + 'trusty_rules');
            if (rawTrustyRules) {
                const parsed = JSON.parse(rawTrustyRules);
                if (Array.isArray(parsed) && parsed.length > 0) return parsed;
            }
        } catch (e) {
            console.warn("[DataManager] Error parsing trusty_rules from localStorage", e);
        }

        // 2. Якщо немає прямого масиву, шукаємо через фільтрацію (для сумісності)
        const items = dataManagerService.filterItemsByType(rulesType);
        if (items.length > 0) return items;

        // 3. Якщо нічого не знайдено - повертаємо дефолт
        return defaultRules;
    },

    /**
     * Отримує опис правил (metadata) з бібліотеки.
     */
    fetchRulesMeta: () => {
        try {
            // Бібліотека rules_meta зберігається під ключем rwd_data_rules_meta
            const rawData = localStorage.getItem(appConstants.localStorageDataPrefix + 'rules_meta');
            const parsed = rawData ? JSON.parse(rawData) : null;
            
            // Якщо в localStorage є дані і це не порожній об'єкт - повертаємо їх
            if (parsed && Object.keys(parsed).length > 0) return parsed;
            
            // Інакше повертаємо дефолтні мета-дані
            return defaultRulesMeta;
        } catch (e) {
            console.error("[DataManager] Error fetching rules meta:", e);
            return defaultRulesMeta;
        }
    },

    /**
     * Утиліта для фільтрації localStorage за типом елемента.
     */
    filterItemsByType: (type) => {
        try {
            const dataPrefix = appConstants.localStorageDataPrefix;
            const allItems = [];

            for (let i = 0; i < localStorage.length; i++) {
                const key = localStorage.key(i);
                if (key && key.startsWith(dataPrefix)) {
                    const rawData = localStorage.getItem(key);
                    if (!rawData) continue;

                    try {
                        const fileContent = JSON.parse(rawData);
                        if (!Array.isArray(fileContent)) continue;

                        fileContent.forEach(item => {
                            if (item?.scenarioItems) {
                                item.scenarioItems
                                    .filter(si => si.type === type && si.translations)
                                    .forEach(si => {
                                        allItems.push({
                                            ...si.translations,
                                            id: si.id || Math.random().toString(36).substr(2, 9),
                                            sourceFile: key
                                        });
                                    });
                            }
                        });
                    } catch (e) {
                        console.warn(`[DataManager] Error parsing ${key}`, e);
                    }
                }
            }
            return allItems;
        } catch (error) {
            console.error("[DataManager] Error filtering items:", error);
            return [];
        }
    }
};
