import { useState, useEffect, useCallback } from 'react';
import { parseDSL } from '../../shared/lib/parser';
import { appConstants } from '../../shared/constants';

export const useDocTree = () => {
    const [tree, setTree] = useState([]);
    const [flatNodes, setFlatNodes] = useState({});
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);

    useEffect(() => {
        const fetchAndParse = async () => {
            try {
                setIsLoading(true);
                const url = appConstants.apiDoctreeUrl;
                // console.log('Fetching DocTree from:', url);
                const response = await fetch(url);
                
                if (!response.ok) {
                    throw new Error(`Не вдалося завантажити конфігурацію: ${response.status} ${response.statusText}`);
                }
                
                const content = await response.text();
                // Перевірка чи ми не отримали HTML замість DSL
                if (content.trim().startsWith('<!DOCTYPE')) {
                    throw new Error("Отримано HTML замість файлу конфігурації. Перевірте шлях apiDoctreeUrl.");
                }

                const parsedTree = parseDSL(content, 'doctree');
                setTree(parsedTree);
                
                const flat = {};
                const traverse = (nodes) => {
                    nodes.forEach(node => {
                        flat[node.id] = node;
                        if (node.children && node.children.length > 0) {
                            traverse(node.children);
                        }
                    });
                };
                traverse(parsedTree);
                setFlatNodes(flat);
                
            } catch (err) {
                console.error('Error loading DocTree:', err);
                setError(err.message);
            } finally {
                setIsLoading(false);
            }
        };

        fetchAndParse();
    }, []);

    const findNodeById = useCallback((id) => {
        return flatNodes[id] || null;
    }, [flatNodes]);

    return { tree, findNodeById, isLoading, error };
};
